import org.junit.jupiter.api.*;

class OptimizationTacticsTest {
    final ObjectMapper json=new ObjectMapper();final AdPlanRepository plans=mock(AdPlanRepository.class);final AdManagementPort ads=mock(AdManagementPort.class);
    final QianchuanCredentialFacade credentials=mock(QianchuanCredentialFacade.class);final OptimizationStore policies=mock(OptimizationStore.class);final OptimizationAutomationStore journal=mock(OptimizationAutomationStore.class);final PlanTransferStore transfers=mock(PlanTransferStore.class);final CreationQianchuanGateway catalog=mock(CreationQianchuanGateway.class);final PlanManagementService management=mock(PlanManagementService.class);final PlanRemoteStore remote=mock(PlanRemoteStore.class);
    final OptimizationTacticsGateway gateway=new OptimizationTacticsGateway(plans,ads,credentials,policies,journal,transfers,catalog,management,remote,json);
    final AdPlan p=plan("p","11"),peer=plan("peer","12"),donor=plan("donor","13");final Credential c=mock(Credential.class);
    AdPlan plan(String id,String qc){var p=mock(AdPlan.class);when(p.id()).thenReturn(new PlanId(id));when(p.name()).thenReturn(PlanName.fromPlatform(id));when(p.tenantId()).thenReturn(new TenantId("t"));when(p.accountId()).thenReturn(new AccountId("a"));when(p.awemeId()).thenReturn(new AwemeId("w"));when(p.qcPlanId()).thenReturn(Optional.of(new QcPlanId(qc)));when(p.status()).thenReturn(PlanStatus.DELIVERING);var setting=mock(DeliverySetting.class);when(setting.bidType()).thenReturn(SmartBidType.CUSTOM);when(p.setting()).thenReturn(setting);return p;}
    ObjectNode detail(String qc,String... products){var d=json.createObjectNode().put("ad_id",qc);var gs=d.putArray("multi_product_creative_list");for(String product:products){var g=gs.addObject().put("product_id",product).put("hide_in_aweme",true);g.putArray("video_material").addObject().put("video_id","v1").put("video_cover_id","cover").put("image_mode","VIDEO_VERTICAL");g.withArray("video_material").addObject().put("video_id","v2").put("video_cover_id","cover2").put("image_mode","VIDEO_VERTICAL");g.putArray("title_material").addObject().put("title","已经审核通过的商品标题");}return d;}
    ObjectNode productRow(String id,boolean losing){var row=json.createObjectNode().put("product_id",id).put("audit_status","PASS");row.putObject("stats_info").put("stat_cost_for_roi2","100").put("total_pay_order_count_for_roi2",losing?"0":"5").put("total_order_settle_amount_for_roi2_1h",losing?"0":"500");return row;}
    ObjectNode materialRow(String qc,String id,String video,boolean losing){var row=productRow("111",losing);row.put("ad_id",qc).put("material_status","DELIVERY_OK");row.putArray("product_info").addObject().put("product_id","111");row.putObject("material_info").putObject("video_material").put("material_id",id).put("video_id",video).put("source","AD");return row;}
    OptimizationPolicy policy(String kind){var base=OptimizationPolicy.defaults();var t=new OptimizationPolicy.Tactics(kind.equals("BOOST"),kind.equals("MATERIAL_FOLLOW"),kind.equals("MATERIAL_ADD"),kind.equals("MATERIAL_REMOVE"),kind.equals("PRODUCT_ADD"),kind.equals("PRODUCT_REMOVE"),new BigDecimal("100"),BigDecimal.ONE,new BigDecimal("300"),2,1,1,kind.endsWith("ADD")?List.of("donor"):List.of());return new OptimizationPolicy(true,"AUTO_LIMITED",base.dailySpendLimit(),base.maxLoss(),base.minSpend(),3,3,60,List.of(),base.automation(),t);}
    ObjectNode action(String kind){var n=json.createObjectNode().put("kind",kind).put("cause",kind.endsWith("REMOVE")?"ENTITY_LOSS":kind.endsWith("ADD")?"PROFITABLE_CANDIDATE":"PERSISTENT_PROFIT");if(kind.equals("BOOST"))n.put("budget","100").put("duration","1");else{n.put("product_id","111").put("entity_id",kind.startsWith("PRODUCT")?"111":"501");if(kind.startsWith("MATERIAL"))n.put("material_type","VIDEO");if(kind.endsWith("ADD"))n.put("source_plan_id","donor");}return n;}
    @BeforeEach void setup(){when(credentials.getUsableCredential(any(),any())).thenReturn(c);when(plans.findById(new TenantId("t"),new PlanId("p"))).thenReturn(Optional.of(p));when(plans.findById(new TenantId("t"),new PlanId("peer"))).thenReturn(Optional.of(peer));when(plans.findById(new TenantId("t"),new PlanId("donor"))).thenReturn(Optional.of(donor));when(plans.findByTenant(any())).thenReturn(List.of(p,peer,donor));when(transfers.group(any(),any())).thenReturn(new PlanTransferStore.Group("p","p","peer","p","optimization:event"));when(ads.detail(c,"11")).thenReturn(detail("11","111","222"));when(ads.detail(c,"12")).thenReturn(detail("12","111","222"));when(ads.detail(c,"13")).thenReturn(detail("13","111"));when(policies.economics(any())).thenReturn(List.of(new OptimizationPolicy.Economics("111",new BigDecimal(".4"),BigDecimal.ZERO,true),new OptimizationPolicy.Economics("222",new BigDecimal(".4"),BigDecimal.ZERO,true)));when(journal.extraBudgetToday(anyString(),anyString())).thenReturn(BigDecimal.ZERO);var product=mock(CreationState.Product.class);when(product.stock()).thenReturn(100L);when(catalog.selected(any(),anyString(),anyString(),any())).thenReturn(List.of(product));}
    @Test void oldPolicyDefaultsDoNotAuthorizeAnyNewAction()throws Exception {var old=json.readTree(json.writeValueAsString(OptimizationPolicy.defaults()));((ObjectNode)old).remove("tactics");assertFalse(json.treeToValue(old,OptimizationPolicy.class).tactics().active());}
    @Test void zeroDeliveryRequiresExplicitCountersForEveryBoundProduct() {
        var day = LocalDate.of(2026, 11, 10);
        var ids = List.of("111", "222");
        var first = productRow("111", true);
        ((ObjectNode) first.path("stats_info")).put("product_show_count_for_roi2", 0).put("stat_cost_for_roi2", 0);
        var second = first.deepCopy().put("product_id", "222");
        when(ads.products(c, "11", day, day)).thenReturn(List.of(), List.of(first), List.of(first, second));
        assertEquals(OptimizationTacticsGateway.DeliveryActivity.UNKNOWN, gateway.productDeliveryActivity(p, day, ids));
        assertEquals(OptimizationTacticsGateway.DeliveryActivity.UNKNOWN, gateway.productDeliveryActivity(p, day, ids));
        assertEquals(OptimizationTacticsGateway.DeliveryActivity.ZERO, gateway.productDeliveryActivity(p, day, ids));
        ((ObjectNode) second.path("stats_info")).put("product_show_count_for_roi2", 1);
        assertEquals(OptimizationTacticsGateway.DeliveryActivity.ACTIVE, gateway.productDeliveryActivity(p, day, ids));
        ((ObjectNode) second.path("stats_info")).remove("product_show_count_for_roi2");
        assertEquals(OptimizationTacticsGateway.DeliveryActivity.UNKNOWN, gateway.productDeliveryActivity(p, day, ids));
    }
    @Test void legacyProductAddPermissionIsDiscardedOnReadAndCannotReachWrite()throws Exception {var raw=json.valueToTree(policy("PRODUCT_ADD"));((ObjectNode)raw.path("tactics")).put("productAdd",true);var old=json.treeToValue(raw,OptimizationPolicy.class);assertFalse(old.tactics().productAdd());assertFalse(old.tactics().active());assertFalse(old.tactics().content());assertEquals(false,old.tactics().engine().get("product_add"));assertThrows(BizException.class,()->gateway.prepare(p,old,action("PRODUCT_ADD"),"event"));var forged=new OptimizationTacticsGateway.Prepared(List.of(new OptimizationTacticsGateway.MemberWrite(p,json.createObjectNode(),json.createObjectNode())),null,"111","task",null);assertThrows(BizException.class,()->gateway.write(p,action("PRODUCT_ADD"),forged));verify(ads,never()).automaticContent(any(),anyString(),anyString(),any());}
    @Test void boostBudget100IsAllowedAndGetsStableUniqueTaskName(){var a=action("BOOST");var prepared=gateway.prepare(p,policy("BOOST"),a,"abc-def");assertEquals("坤境自动_abcdef",prepared.taskName());gateway.write(p,a,prepared);verify(ads).automaticControl(c,"11","SMART_BOOST","坤境自动_abcdef",new BigDecimal("100"),BigDecimal.ONE,List.of());}
    @Test void boostReadbackRequiresDurationAndUniqueNonRejectedTask(){var a=action("BOOST");var intent=gateway.intent(gateway.prepare(p,policy("BOOST"),a,"event"));var task=json.createObjectNode().put("id","701").put("name","坤境自动_event").put("task_status","PROCESSING").put("budget","100").put("duration","2");when(ads.controls(c,"11","SMART_BOOST")).thenReturn(List.of(task));assertFalse(gateway.matches(p,a,intent));task.put("duration","1");assertTrue(gateway.matches(p,a,intent));when(ads.controls(c,"11","SMART_BOOST")).thenReturn(List.of(task,task));assertFalse(gateway.matches(p,a,intent));when(ads.controls(c,"11","SMART_BOOST")).thenReturn(List.of(task));task.put("task_status","FROZEN");assertFalse(gateway.matches(p,a,intent));}
    @Test void materialFollowUsesMatureEligibleVideoAndVerifiesExactMaterial(){when(management.materials(new TenantId("t"),new PlanId("p"))).thenReturn(List.of(new PlanManagementService.Material("501","video","cover","PASS","DELIVERY_OK",true,null,100L)));when(ads.materialReport(eq(c),eq("11"),any(),any(),eq("VIDEO"))).thenReturn(List.of(materialRow("11","501","v1",false)));var a=action("MATERIAL_FOLLOW").put("budget","100").put("duration","1");var prepared=gateway.prepare(p,policy("MATERIAL_FOLLOW"),a,"event");gateway.write(p,a,prepared);verify(ads).automaticControl(c,"11","MATERIAL_ADD_BUDGET","坤境自动_event",new BigDecimal("100"),BigDecimal.ONE,List.of("501"));var task=json.createObjectNode().put("id","701").put("name","坤境自动_event").put("task_status","PROCESSING").put("budget","100").put("duration","1");task.putArray("material_list").addObject().put("material_id","502");when(ads.controls(c,"11","MATERIAL_ADD_BUDGET")).thenReturn(List.of(task));var intent=gateway.intent(prepared);assertFalse(gateway.matches(p,a,intent));((ObjectNode)task.path("material_list").get(0)).put("material_id","501");assertTrue(gateway.matches(p,a,intent));}
    @Test void pausedTaskBlocksDuplicateBoost(){when(ads.controls(c,"11")).thenReturn(List.of(json.createObjectNode().put("task_status","DISABLE")));assertThrows(BizException.class,()->gateway.prepare(p,policy("BOOST"),action("BOOST"),"event"));verify(ads,never()).automaticControl(any(),anyString(),anyString(),anyString(),any(),any(),any());}
    @Test void legacyDonorPoolIsRetiredEvenForOtherAccounts(){assertTrue(gateway.candidates(p).isEmpty());assertTrue(policy("MATERIAL_ADD").tactics().candidatePlanIds().isEmpty());assertFalse(policy("MATERIAL_ADD").tactics().materialAdd());}
    @Test void productDeletionSynchronizesBothMembersAndRequiresBothReadbacks(){when(ads.monitoringProducts(eq(c),eq("11"),any(),any())).thenReturn(List.of(productRow("111",true)));var a=action("PRODUCT_REMOVE");var prepared=gateway.prepare(p,policy("PRODUCT_REMOVE"),a,"event");assertEquals(2,prepared.writes().size());gateway.write(p,a,prepared);verify(ads).automaticContent(eq(c),eq("11"),eq("PRODUCT_REMOVE"),any());verify(ads).automaticContent(eq(c),eq("12"),eq("PRODUCT_REMOVE"),any());var intent=gateway.intent(prepared);when(ads.detail(c,"11")).thenReturn(detail("11","222"));assertFalse(gateway.matches(p,a,intent));when(ads.detail(c,"12")).thenReturn(detail("12","222"));assertTrue(gateway.matches(p,a,intent));}
    @Test void lastProductOfAnyMemberStopsAllWrites(){when(ads.monitoringProducts(eq(c),eq("11"),any(),any())).thenReturn(List.of(productRow("111",true)));when(ads.detail(c,"12")).thenReturn(detail("12","111"));assertThrows(BizException.class,()->gateway.prepare(p,policy("PRODUCT_REMOVE"),action("PRODUCT_REMOVE"),"event"));verify(ads,never()).automaticContent(any(),anyString(),anyString(),any());}
    @Test void materialRemovalUsesEachMembersOwnMaterialId(){when(ads.materialReport(eq(c),eq("11"),any(),any(),eq("VIDEO"))).thenReturn(List.of(materialRow("11","501","v1",true),materialRow("11","502","v2",false)));when(ads.materialReport(eq(c),eq("12"),any(),any(),eq("VIDEO"))).thenReturn(List.of(materialRow("12","601","v1",true),materialRow("12","602","v2",false)));var a=action("MATERIAL_REMOVE");var prepared=gateway.prepare(p,policy("MATERIAL_REMOVE"),a,"event");assertEquals(List.of("501","601"),prepared.writes().stream().map(w->w.payload().path("materialId").asText()).toList());}
    @Test void missingNetRevenueBlocksDeletionInsteadOfAssumingZero(){var row=productRow("111",true);((ObjectNode)row.path("stats_info")).remove("total_order_settle_amount_for_roi2_1h");when(ads.monitoringProducts(eq(c),eq("11"),any(),any())).thenReturn(List.of(row));assertThrows(BizException.class,()->gateway.prepare(p,policy("PRODUCT_REMOVE"),action("PRODUCT_REMOVE"),"event"));}
    @Test void deletionCannotLeaveOnlyAnUnreviewedMaterial(){
        var unreviewed=materialRow("11","502","v2",false);unreviewed.put("audit_status","AUDITING");
        when(ads.materialReport(eq(c),eq("11"),any(),any(),eq("VIDEO"))).thenReturn(List.of(materialRow("11","501","v1",true),unreviewed));
        when(ads.materialReport(eq(c),eq("12"),any(),any(),eq("VIDEO"))).thenReturn(List.of(materialRow("12","601","v1",true),materialRow("12","602","v2",false)));
        assertThrows(BizException.class,()->gateway.prepare(p,policy("MATERIAL_REMOVE"),action("MATERIAL_REMOVE"),"event"));
        verify(ads,never()).automaticContent(any(),anyString(),anyString(),any());
    }
    @Test void donorAdditionCannotReachPlatformEvenWhenHistoricallyProfitable(){assertThrows(BizException.class,()->gateway.prepare(p,policy("MATERIAL_ADD"),action("MATERIAL_ADD"),"event"));verify(ads,never()).automaticContent(any(),anyString(),anyString(),any());}
    @Test void malformedBindingAndUnknownActionNeverProducePayload(){assertThrows(BizException.class,()->OptimizationTacticsGateway.groups(json.createObjectNode()));assertThrows(BizException.class,()->OptimizationTacticsGateway.validateAction(policy("BOOST"),action("SEARCH"),json.createObjectNode(),ZonedDateTime.now(ZoneId.of("Asia/Shanghai"))));}
    @Test void generatedAdditionRequiresLocalProvenanceAndPreservesPeerGoodsTitlesAndSettings()throws Exception{
        var store=mock(OptimizationCreativeStore.class);var builder=mock(com.lynx.ad.modules.delivery.application.CreationPayloadBuilder.class);gateway.creative(store,builder);
        var base=policy("MATERIAL_ADD");var g=OptimizationPolicy.CreativeGeneration.defaults();var enabled=new OptimizationPolicy.CreativeGeneration(true,false,g.formats(),2,2,g.dailyCostLimit(),g.perAssetCostLimit(),g.trialLossLimit(),1000,50,"","","user");
        var config=new OptimizationPolicy(true,"AUTO_LIMITED",base.dailySpendLimit(),base.maxLoss(),base.minSpend(),3,3,60,List.of(),base.automation(),base.tactics(),enabled);
        when(policies.get(p.tenantId(),p.id())).thenReturn(Optional.of(new OptimizationStore.State("t","p",3,true,config,null,null,null,null)));
        var product=mock(CreationState.Product.class);when(product.qcProductId()).thenReturn("111");when(product.stock()).thenReturn(10L);when(product.imageUrl()).thenReturn("https://example.invalid/ref.png");when(catalog.selected(any(),anyString(),anyString(),eq(List.of("111")))).thenReturn(List.of(product));
        var body=json.createObjectNode().put("engine_job_id","engine-job").put("approved",true);body.set("material",json.readTree("{\"engineJobId\":\"engine-job\",\"productId\":\"111\",\"type\":\"VIDEO\"}"));
        var job=new OptimizationCreativeStore.Job("generation","t","p","p","a","111",3,"PUBLISHING",BigDecimal.TEN,body,Instant.now(),null);
        when(store.publication("t","generation","p",3)).thenReturn(job);
        when(builder.optimizationMaterial(any(),any())).thenReturn((ObjectNode)json.readTree("{\"product_id\":111,\"video_material\":[{\"video_id\":\"v3\",\"video_cover_id\":\"cover3\",\"image_mode\":\"VIDEO_VERTICAL\"}],\"title_material\":[{\"title\":\"新增素材真实选购标题\",\"title_type\":\"CUSTOM\"}]}"));
        var a=json.createObjectNode().put("kind","MATERIAL_ADD").put("cause","NEW_MATERIAL_TRIAL").put("generation_id","generation").put("product_id","111");
        var prepared=gateway.prepare(p,config,a,"event");assertEquals(2,prepared.writes().size());
        for(var write:prepared.writes()){var gs=write.payload().path("creatives");assertEquals(2,gs.size());assertEquals(3,gs.get(0).path("video_material").size());assertEquals(2,gs.get(0).path("title_material").size());assertTrue(gs.get(0).path("hide_in_aweme").asBoolean());assertFalse(write.payload().has("delivery_setting"));}
        gateway.write(p,a,prepared);verify(ads).automaticContent(eq(c),eq("11"),eq("MATERIAL_ADD"),any());verify(ads).automaticContent(eq(c),eq("12"),eq("MATERIAL_ADD"),any());
        body.put("approved",false);assertThrows(BizException.class,()->gateway.prepare(p,config,a,"event"));
    }
    @Test void addingCardDoesNotDuplicateTheRequiredCommodityTitle()throws Exception{
        var current=(ObjectNode)json.readTree("{\"product_id\":111,\"title_material\":[{\"title\":\"原商品卡标题\",\"title_type\":\"COMMODITY_CARD\"}]}");
        var single=json.readTree("{\"product_id\":111,\"image_material\":[{\"image_mode\":\"SQUARE\",\"image_ids\":[\"image-original-id\"]}],\"title_material\":[{\"title\":\"新商品卡标题\",\"title_type\":\"COMMODITY_CARD\"}]}");
        OptimizationTacticsGateway.mergeGenerated(current,single);assertEquals("COMMODITY_CARD",current.path("title_material").get(0).path("title_type").asText());assertEquals("CUSTOM",current.path("title_material").get(1).path("title_type").asText());assertEquals("image-original-id",current.path("image_material").get(0).path("image_ids").get(0).asText());
        assertThrows(BizException.class,()->OptimizationTacticsGateway.mergeGenerated(current,single));
    }
}
